<?php
namespace Azuriom\Plugin\GamingHubCore\Services;
use Azuriom\Plugin\GamingHubCore\Contracts\SharedDataGateway; use Azuriom\Plugin\GamingHubCore\Data\PublicServerData; use Azuriom\Plugin\GamingHubCore\Models\Server; use Throwable;
final class PublicServerPresenter { public function __construct(private SharedDataGateway $gateway){} public function make(Server $server,bool $includeProviders=false):PublicServerData{$status=null;$message=null;$source=null;$players=null;$maximum=null;try{$r=$this->gateway->publicRead($server,'server-status');$status=is_string($r->data['server.state']??null)?$r->data['server.state']:null;$message=$this->str($r->data['server.message']??null);$source=$this->str($r->sourceLabel);$players=is_numeric($r->data['players.current']??null)?(int)$r->data['players.current']:null;$maximum=is_numeric($r->data['players.maximum']??null)?(int)$r->data['players.maximum']:null;}catch(Throwable){$status=null;}return new PublicServerData((int)$server->getKey(),(string)$server->game->slug,(string)$server->slug,(string)$server->name,$this->str($server->short_description),$this->str($server->long_description),$this->str($server->icon_url),$this->str($server->banner_url),(int)$server->position,$status,$message,$this->str($server->hostname),$server->display_port===null?null:(int)$server->display_port,$this->str($server->join_url),[], $players,$maximum,$source);} private function str(mixed $v):?string{return is_string($v)&&trim($v)!==''?trim($v):null;} }
